// Shared roster in S.cleaners. Per-checkout assignments live on each ops row
// (cleanerName / cleanDone / cleanTask / cleanTaskNote). Fixed daily blocks
// (ρεπό / άδειες / οδηγοί / ιματισμός) live in S.daily.extra[date].

function _opsExtraCleanRows(date, turnoverKeys) {
  const out = [];
  const seen = new Set(turnoverKeys || []);
  const day = (typeof parseD === 'function') ? parseD(date) : null;
  if (!day) return out;
  const parts = String(date).split('-');
  if (parts.length !== 3) return out;
  const todayDMY = parseInt(parts[2], 10) + '/' + parseInt(parts[1], 10) + '/' + parts[0];

  (S.apts || []).forEach(function (apt) {
    const key = apt.id || apt.name;
    if (seen.has(key)) return;
    const arr = (S.bks || []).find(function (b) {
      return (b.aptId === apt.id || b.aptName === apt.name) &&
        (b.checkIn === date || b.checkIn === todayDMY) && !b.cancelled;
    });
    if (!arr) return;
    let lastCo = null;
    (S.bks || []).forEach(function (b) {
      if ((b.aptId === apt.id || b.aptName === apt.name) && b.checkOut && !b.cancelled) {
        const co = parseD(b.checkOut);
        if (co && co < day && (!lastCo || co > lastCo)) lastCo = co;
      }
    });
    if (lastCo) {
      const gap = Math.round((day - lastCo) / 86400000);
      if (gap >= 4) {
        seen.add(key);
        out.push({
          aptId: apt.id || '', aptName: apt.name || '', cleanType: 'refresh',
          cleanerName: '', cleanDone: false, cleanTask: '', cleanTaskNote: '',
          _gapDays: gap
        });
      }
    }
  });

  (S.bks || []).forEach(function (b) {
    if (b.cancelled) return;
    const arrivesToday = (b.checkIn === date || b.checkIn === todayDMY);
    if (!arrivesToday) return;
    const wants = b.needsSofaBed || /\bsofa[\s-]?bed\b/i.test(String(b.guestName || ''));
    if (!wants) return;
    const key = b.aptId || b.aptName;
    if (seen.has(key)) return;
    seen.add(key);
    out.push({
      aptId: b.aptId || '', aptName: b.aptName || '', cleanType: 'sofa_bed',
      cleanerName: '', cleanDone: false, cleanTask: 'prepare_sofa', cleanTaskNote: ''
    });
  });
  return out;
}

