function opsAddCleaner() {
  const inp = document.getElementById('cleaner-new');
  if (!inp) return;
  const name = inp.value.trim();
  if (!name) return;
  if (!Array.isArray(S.cleaners)) S.cleaners = [];
  if (!S.cleaners.some(function (n) { return n.toLowerCase() === name.toLowerCase(); })) {
    S.cleaners.push(name);
    S.cleaners.sort(function (a, b) { return a.localeCompare(b); });
